"use client";
import { useEffect, useRef, useState, type ReactNode } from "react";
import { useDrag } from "./use-drag";
import { cn } from "./cn";
import { haptic } from "./haptics";
import { useDoubleTap } from "./use-double-tap";

const START = 135, SWEEP = 270; // degrees, clockwise from 3 o'clock; the gap is at the bottom
const pt = (cx: number, r: number, deg: number) => [cx + r * Math.cos((deg * Math.PI) / 180), cx + r * Math.sin((deg * Math.PI) / 180)];
const arc = (cx: number, r: number, a: number, b: number) => { const [x1, y1] = pt(cx, r, a), [x2, y2] = pt(cx, r, b); return `M${x1} ${y1}A${r} ${r} 0 ${b - a > 180 ? 1 : 0} 1 ${x2} ${y2}`; };

export interface DialProps {
  value: number;
  min: number;
  max: number;
  /** Size of one step: the dial snaps to multiples of it. */
  step?: number;
  /** Called with the chosen value when the finger lifts. */
  onCommit: (v: number) => void;
  /** Names the dial for screen readers: "Target temperature". */
  label: string;
  /** Shown after the value for screen readers ("24 degrees"), for example "°". */
  unit?: string;
  className?: string;
  /** Double-tap the dial to return to this value (a default). Leave it out for no reset. */
  resetValue?: number;
  /** A second marker on the track (the room's current temperature). */
  marker?: number;
  /** Colour of the filled arc. */
  color?: string;
  /** Show live while dragging (for the centre text). */
  children?: (v: number) => ReactNode;
}

/** Radial dial: drag around a 270° arc. Previews while dragging, commits on release. */
export function Dial({ value, min, max, step = 1, onCommit, label, unit = "", marker, color = "var(--glow)", className, resetValue, children }: DialProps) {
  const [v, setV] = useState(value);
  const dragging = useRef(false);
  const prev = useRef(value);
  useEffect(() => { if (!dragging.current) setV(value); }, [value]);
  const at = (x: number, y: number) => {
    let deg = (Math.atan2(y - 0.5, x - 0.5) * 180) / Math.PI; if (deg < 0) deg += 360;
    let rel = deg - START; if (rel < 0) rel += 360;
    if (rel > SWEEP) rel = rel - SWEEP < (360 - SWEEP) / 2 ? SWEEP : 0; // in the gap: snap to the nearer end
    const raw = min + (rel / SWEEP) * (max - min);
    return Math.min(max, Math.max(min, Math.round(raw / step) * step));
  };
  const dbl = useDoubleTap(() => { if (resetValue !== undefined) { haptic("medium"); prev.current = resetValue; setV(resetValue); onCommit(resetValue); } });
  const drag = useDrag((x, y) => {
    dragging.current = true;
    const n = at(x, y);
    // jumping across the gap in one move is a wrap, not a drag
    if (Math.abs(n - prev.current) > (max - min) * 0.6) return;
    if (n !== prev.current) {
      const q = (x: number) => Math.floor(((x - min) / (max - min)) * 4), was = prev.current;
      if ((n <= min || n >= max) && was > min && was < max) haptic("boundary"); // reached an end: a bump
      else if (q(n) !== q(was)) haptic("detent"); // a quarter of the way
      else haptic("tick");
      prev.current = n; setV(n);
    }
  }, () => { dragging.current = false; onCommit(prev.current); });
  const f = (n: number) => (n - min) / (max - min);
  const S = 220, cx = S / 2, r = 90, end = START + SWEEP * f(v);
  const [kx, ky] = pt(cx, r, end);
  const m = marker !== undefined && marker >= min && marker <= max ? pt(cx, r + 14, START + SWEEP * f(marker)) : null;
  return (
    <div data-slot="dial" className={cn("dial", className)} role="slider" aria-label={label} aria-valuemin={min} aria-valuemax={max} aria-valuenow={v} aria-valuetext={`${v}${unit}`} tabIndex={0} {...drag} onPointerDown={(e) => { drag.onPointerDown(e); if (resetValue !== undefined) dbl.onPointerDown(e); }} onPointerUp={(e) => { drag.onPointerUp(e); if (resetValue !== undefined) dbl.onPointerUp(e); }}
      onKeyDown={(e) => { const d = e.key === "ArrowRight" || e.key === "ArrowUp" ? step : e.key === "ArrowLeft" || e.key === "ArrowDown" ? -step : 0; if (d) { const n = Math.min(max, Math.max(min, v + d)); prev.current = n; setV(n); onCommit(n); } }}>
      <svg viewBox={`0 0 ${S} ${S}`} aria-hidden>
        <path d={arc(cx, r, START, START + SWEEP)} className="dial-t" />
        {f(v) > 0 ? <path d={arc(cx, r, START, Math.max(START + 0.01, end))} className="dial-f" style={{ stroke: color }} /> : null}
        {m ? <circle cx={m[0]} cy={m[1]} r="3.5" className="dial-m" /> : null}
        <circle cx={kx} cy={ky} r="14" className="dial-k" />
      </svg>
      <div className="dial-c">{children ? children(v) : <b className="num">{v}{unit}</b>}</div>
    </div>
  );
}

.dial{position:relative;width:min(240px,66vw);aspect-ratio:1;margin:0 auto;touch-action:none;cursor:pointer;-webkit-user-select:none;user-select:none}
.dial svg{width:100%;height:100%;overflow:visible}
.dial-t,.dial-f{fill:none;stroke-width:16;stroke-linecap:round}
.dial-t{stroke:var(--tile2)}
.dial-k{fill:var(--tile);stroke:var(--ink);stroke-width:3;filter:drop-shadow(0 2px 4px rgba(0,0,0,.3))}
.dial:active .dial-k{r:16}
.dial-m{fill:var(--ink)}
.dial-c{position:absolute;inset:0;display:grid;place-content:center;text-align:center;pointer-events:none;font-variant-numeric:tabular-nums}
.dial-c .num{font:760 3.4rem/1 var(--f-display);letter-spacing:-.03em}
.dial:focus-visible{outline:2px solid var(--ink);outline-offset:4px;border-radius:50%}
.chips{display:flex;flex-wrap:wrap;gap:8px;justify-content:center}
.chips .btn[aria-pressed=true]{background:var(--glow-soft);color:var(--glow-ink)}
.dt .dico.spin svg{animation:dspin var(--spin,1s) linear infinite}
@keyframes dspin{to{rotate:360deg}}
@media (prefers-reduced-motion:reduce){.dt .dico.spin svg{animation:none}}

"use client";
import { useRef, type PointerEvent } from "react";

/** Where the pointer is, as fractions of the element, *not* clamped: below 0 or above 1 means it is past the edge (for rubber-banding). */
export interface DragRaw { x: number; y: number }

/** How fast the pointer was moving when it lifted, as fractions of the element per second (positive is right and down). */
export interface DragVelocity { vx: number; vy: number }

/**
 * Where something flicked from `pos` (0 to 1) with velocity `vel` (fractions per second) comes to rest. A flick carries on after the
 * finger lifts, the way a scroll view does: the distance is the sum of a decelerating glide. `rate` is how quickly it slows
 * (0.998 glides a long way, 0.99 a short one). The result is not clamped.
 */
export const project = (pos: number, vel: number, rate = 0.99) => pos + ((vel / 1000) * rate) / (1 - rate);

const WINDOW_MS = 90; // velocity is read from the last moments of the drag, not its whole length

/**
 * Pointer-capture drag over an element. `move` gets the pointer as 0 to 1 fractions of the element's box (clamped), and as a fourth
 * argument the same position unclamped (so a control can stretch when pulled past its end);
 * `end` fires on release with the last position and the velocity at the moment of release (use it with `project`
 * to let a flick carry on). Props go on the element itself.
 */
export function useDrag(
  move: (x: number, y: number, el: HTMLElement, raw: DragRaw) => void,
  end?: (x: number, y: number, el: HTMLElement, v: DragVelocity) => void,
) {
  const live = useRef(false);
  const last = useRef<[number, number]>([0, 0]);
  const raw = useRef<DragRaw>({ x: 0, y: 0 });
  const trail = useRef<{ t: number; x: number; y: number }[]>([]);
  const at = (e: PointerEvent<HTMLElement>): [number, number] => {
    const r = e.currentTarget.getBoundingClientRect();
    raw.current = { x: (e.clientX - r.left) / r.width, y: (e.clientY - r.top) / r.height };
    return [Math.min(1, Math.max(0, raw.current.x)), Math.min(1, Math.max(0, raw.current.y))];
  };
  const note = () => {
    const now = performance.now(), [x, y] = last.current;
    trail.current.push({ t: now, x, y });
    while (trail.current.length > 1 && now - trail.current[0].t > WINDOW_MS) trail.current.shift();
  };
  const velocity = (): DragVelocity => {
    const a = trail.current[0], b = trail.current[trail.current.length - 1];
    const dt = a && b ? b.t - a.t : 0;
    return dt > 8 ? { vx: ((b.x - a.x) / dt) * 1000, vy: ((b.y - a.y) / dt) * 1000 } : { vx: 0, vy: 0 };
  };
  return {
    onPointerDown: (e: PointerEvent<HTMLElement>) => { live.current = true; trail.current = []; e.currentTarget.setPointerCapture(e.pointerId); last.current = at(e); note(); move(...last.current, e.currentTarget, raw.current); },
    onPointerMove: (e: PointerEvent<HTMLElement>) => { if (!live.current) return; last.current = at(e); note(); move(...last.current, e.currentTarget, raw.current); },
    onPointerUp: (e: PointerEvent<HTMLElement>) => { if (!live.current) return; live.current = false; end?.(...last.current, e.currentTarget, velocity()); },
    onPointerCancel: () => { live.current = false; },
    "data-base-ui-swipe-ignore": true,
  } as const;
}
